class Solution {
public:
    int countCompleteComponents(int n, std::vector<std::vector<int>>& edges) {
        std::vector<std::vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        std::vector<bool> visited(n, false);
        int ans = 0;
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                std::vector<int> q = {i};
                visited[i] = true;
                int head = 0;
                int total_deg = 0;
                while (head < (int)q.size()) {
                    int u = q[head++];
                    total_deg += adj[u].size();
                    for (int v : adj[u]) {
                        if (!visited[v]) {
                            visited[v] = true;
                            q.push_back(v);
                        }
                    }
                }
                int k = q.size();
                if (total_deg / 2 == k * (k - 1) / 2) {
                    ans++;
                }
            }
        }
        return ans;
    }
};

class Solution {
    public int countCompleteComponents(int n, int[][] edges) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        boolean[] visited = new boolean[n];
        int ans = 0;
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                List<Integer> q = new ArrayList<>();
                q.add(i);
                visited[i] = true;
                int head = 0;
                int totalDeg = 0;
                while (head < q.size()) {
                    int u = q.get(head++);
                    totalDeg += adj.get(u).size();
                    for (int v : adj.get(u)) {
                        if (!visited[v]) {
                            visited[v] = true;
                            q.add(v);
                        }
                    }
                }
                int k = q.size();
                if (totalDeg / 2 == k * (k - 1) / 2) {
                    ans++;
                }
            }
        }
        return ans;
    }
}

var countCompleteComponents = function(n, edges) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    const visited = new Array(n).fill(false);
    let ans = 0;
    for (let i = 0; i < n; i++) {
        if (!visited[i]) {
            const q = [i];
            visited[i] = true;
            let head = 0;
            let totalDeg = 0;
            while (head < q.length) {
                const u = q[head++];
                totalDeg += adj[u].length;
                for (const v of adj[u]) {
                    if (!visited[v]) {
                        visited[v] = true;
                        q.push(v);
                    }
                }
            }
            const k = q.length;
            if (Math.floor(totalDeg / 2) === Math.floor((k * (k - 1)) / 2)) {
                ans++;
            }
        }
    }
    return ans;
};
